{
  "title": "Aquarium controls",
  "description": "Each control writes to nb, and the aquarium below follows along.",
  "width": 900,
  "height": 84,
  "controls": [
    { "type": "slider", "label": "Fish in the tank", "bind": "fish_count", "default": 12, "min": 1, "max": 30, "step": 1, "x": 0, "y": 0, "width": 210, "height": 64 },
    { "type": "slider", "label": "Water temperature", "bind": "water_temp", "default": 24, "min": 18, "max": 30, "step": 1, "suffix": " °C", "x": 230, "y": 0, "width": 210, "height": 64 },
    { "type": "checkbox", "label": "Bubbles", "bind": "bubbles", "default": true, "x": 460, "y": 14, "width": 210, "height": 42 },
    { "type": "button", "label": "Feed the fish", "icon": "fa-fish", "bind": "food_drops", "action": "increment", "x": 690, "y": 14, "width": 210, "height": 42 }
  ]
}

// One circle per species in its own colour, with its name beside it.
const fish = nb.get('fish') ?? [];

// Put each name where there's room: when several fish share a speed, the
// left-most one is labelled on its left and the rest on their right.
const values = fish.map((f) => {
  const sameSpeed = fish.filter((g) => g.speed === f.speed);
  const leftMost = sameSpeed.length > 1 && sameSpeed.every((g) => g.length_cm >= f.length_cm);
  return { ...f, side: leftMost ? 'left' : 'right' };
});
const label = (side) => ({
  transform: [{ filter: `datum.side === '${side}'` }],
  mark: { type: 'text', align: side === 'left' ? 'right' : 'left', dx: side === 'left' ? -14 : 14, fontSize: 12 },
  encoding: { text: { field: 'name' } },
});

return {
  $schema: 'https://vega.github.io/schema/vega-lite/v5.json',
  title: 'Big fish, fast fish?',
  width: 560,
  height: 300,
  data: { values },
  encoding: {
    x: { field: 'length_cm', type: 'quantitative', title: 'Length (cm)', scale: { domain: [0, 18] } },
    y: { field: 'speed', type: 'quantitative', title: 'Speed (1 slow, 5 fast)', scale: { domain: [0, 5.5] }, axis: { tickMinStep: 1 } },
  },
  layer: [
    {
      mark: { type: 'circle', size: 420, opacity: 0.9, stroke: '#334155', strokeWidth: 1 },
      encoding: {
        color: { field: 'colour', type: 'nominal', scale: null },
        tooltip: [
          { field: 'name', title: 'Fish' },
          { field: 'length_cm', title: 'Length (cm)' },
          { field: 'speed', title: 'Speed' },
          { field: 'zone', title: 'Zone' },
        ],
      },
    },
    label('left'),
    label('right'),
  ],
};
